#!/usr/bin/env python3
"""Publish NEW genuinely heldout industrial visual anomaly findings, source-linked.

Requires 134 frozen source JPEG/PNG file hashes from original MVTec LOCO AD
splicing connectors source, 134 original image-only CLIP global/patch+HSV
features, scores calibrated from 20 NORMAL validation only, 90 true heldout
images scored and then joined to independent ORIGINAL authors' anomaly source
category labels (30 clean/30 logical/30 structural), no posthoc threshold fit.

Original industrial photos CC BY-NC-SA 4.0 research only; DO NOT commit photos,
CLIP weights, pixel embeddings, original per-source prediction rows or source
paths/identities; project report only compact numerical counts/CI and SHA
linkage to private untouched research archive under /data/var. No general
engineering-strength/3D CAD or photorealism quality claims from this benchmark.
"""
from pathlib import Path
import json,hashlib,statistics,datetime
RAW=Path('/data/var/perceptual-independent-20261024/mvtec-loco-splicing-20261025')
DOC=Path(__file__).resolve().parents[2]/'docs/research'
OUT=DOC/'perceptual-mvtec-splicing-new-industrial-anomaly-evidence-2026-10-25.json'
REPORT=DOC/'perceptual-mvtec-splicing-industrial-visual-review-2026-10-25.md'
METHODS=['CLIP_global_nearest_normal','HSV_spatial_hist_nearest_normal','CLIP_p95_patch_memory']
GROUPS=['logical_vs_real_clean','structural_vs_real_clean','all_source_anomalies_vs_original_clean']

def get(name):
 raw=(RAW/name).read_bytes();return json.loads(raw),hashlib.sha256(raw).hexdigest()

def pct(x):return 'n/a' if x is None else f'{x*100:.1f}%'

def run():
 if OUT.exists() or REPORT.exists():print('EXISTING_REAL_INDUSTRIAL_REPORT_PRESERVED_NO_REWRITE');return
 m,ms=get('source_frozen_pre_analysis_selection_20261025.json')
 receipts,hs=get('original_source_image_134_SHA256_receipts_20261025.json')
 vectors,hv=get('134_original_image_visual_feature_capture_state_20261025.json')
 scores,hsc=get('industrial_134_image_scores_normal_only_frozen_before_gold_20261025.json')
 evaluated,hev=get('industrial_90_heldout_good_logical_structural_confusions_20261025.json')
 assert len(m['selected'])==len(receipts['completed'])==len(vectors['cases'])==len(scores['frozen_all_input_scores_by_anonymous_sha_source_ID'])==134
 assert vectors['status']==scores['status']=='complete'
 assert scores['source_original_image_selection_sha256']==ms
 assert evaluated['source_selection_SHA256']==ms and evaluated['frozen_pixel_and_CV_predictions_SHA256']==hsc
 assert scores['image_pixel_features_frozen_sha256']==hv
 assert evaluated['n_original_heldout_test_images']==90
 assert evaluated['trained_normal_source_only']==24 and evaluated['calibration_source_images_only_normal']==20
 assert set(evaluated['method_results'])==set(METHODS)
 assert set(evaluated['source_original_split_counts'])=={'test/good','test/logical_anomalies','test/structural_anomalies'}
 assert all(n==30 for n in evaluated['source_original_split_counts'].values())
 compact={}
 rows=[]
 for name in METHODS:
  compact[name]={}
  for g in GROUPS:
   row=evaluated['method_results'][name][g]
   expected_good=30;expected_bad=60 if g.startswith('all_') else 30
   assert row['TP']+row['FN']==expected_bad and row['TN']+row['FP']==expected_good
   compact[name][g]=row
  row=compact[name]['all_source_anomalies_vs_original_clean']
  rows.append(f"| {name.replace('_',' ')} | {row['TP']}/{row['TP']+row['FN']} | {row['FP']}/{row['FP']+row['TN']} | {row['FN']} | {pct(row['source_original_test_ROC_AUC'])} | {row['image_stratified_bootstrap_95pct_ROC_AUC']} |")
 state={'date':'2026-10-25','status':'PARTIAL — new externally source-labelled industrial defect evidence, normal-only calibrated models evaluated, but no industrial automatic-release reliability established for unrelated machinery','source':'MVTec LOCO AD original industrial splicing connectors, HF public pinned Rafa612/mvtec_loco replica, original lab photography and author source ground-truth category labels','source_repo':'Rafa612/mvtec_loco','official_HF_revision':m['official_replica_revision'],'dataset_official_citation':'Bergmann et al Beyond Dents and Scratches: Logical Constraints in Unsupervised Anomaly Detection and Localization, IJCV 2022','license':'MVTec CC BY-NC-SA 4.0 noncommercial research, no original model image data or redistributed photos in SWAAG Git','owner_general_relevance':'External real component-assembly logical and structural defects visible in camera photos, closer to machinery missing/incorrect parts than source-graph toy fixtures, not proof of CAD contact, photorealistic 3D or physical load capacity.','source_only_private_SHA256':{'precommitted_image_selection_and_orig_split':ms,'original134_image_source_hash_receipt':hs,'pixel_only_134_image_CLIP_ViT32_and_HSV_features':hv,'normal_only_calibrated_134_continuous_scores_before_test_gold':hsc,'frozen_threshold_original_ground_truth_90_eval':hev},'sample':{'train_source_good_original_images':24,'normal_source_validation_images_used_for_95pct_score_cutoff':20,'source_original_test_good':30,'source_original_test_logical_anomalies':30,'source_original_test_structural_anomalies':30,'total_raw_original_source_images':134,'source_image_bytes_MB':m['total_original_download_MB'],'source_train_validation_test_disjoint':True,'selection_hash_frozen_before_model_inference':True},'methods':{'CLIP_global_nearest_normal':'Existing pretrained frozen OpenAI CLIP ViT-B/32 image embedding to nearest of 24 original train good embeddings; 95th percentile of 20 original normal validation score','HSV_spatial_hist_nearest_normal':'Original 2x4 tile HSV 8x4x4 1024D spatial histogram, nearest of same 24 train-good; 95th percentile of same 20 validation normal scores','CLIP_p95_patch_memory':'Existing pretrained CLIP ViT32 last-hidden 49 visual patches, 768D per patch compared to 1176 normal patch tokens, 95th nearest-neighbor patch anomaly percentile; NOT official PatchCore/EfficientAD; normal-only calibration on same20'},'original_heldout_score_and_errors':compact,'frozen_normal_only_thresholds':scores['per_method_precalibrated_cutoffs_20_normal_only'],'local_resource':{'GPU_used':False,'pixel_feature_CPU_wall_s':vectors.get('wall_s'),'pixel_feature_peak_RSS_KB':vectors.get('rss_peak_kb'),'frozen_transformers_checkpoint_sha256':vectors['source_model_weights_sha256'],'cpu_threads':1,'source_bytes_and_images_outside_Git':True},'limits':['The 134 original source photos are copyrighted CC BY-NC-SA, academic noncommercial research only; nothing published as production model training assets.','Only one actual industrial product family, not unrelated forklift and rack photography; no load/mesh support or design intent measured.','Source image labels created by MVTec researchers, not independently re-annotated by this agent, and some original masks could be incomplete.','CLIP pretrained general visual embeddings may have been exposed to MVTec images during original pretraining; historical checkpoint data exposure is not established.','HSV raw pixel baseline has no external pretraining, CLIP has broad image pretraining; equivalent local training/calibration numbers do NOT mean equal cumulative pretraining budget.','Only 20 normal validation images determine threshold, 30 clean test images remain, so false positive rate has broad confidence; no test threshold optimization allowed.','No local generative VLM or specialized EffcientAD model tested for this category; old 18 MVTec Pushpins results not reused or falsely counted as new data.','Declaring individual normal-only test failure does not prove semantic absence/placement correctness or photorealistic generated 3D.','Any alternative method selected after viewing this dataset would require a completely untouched second source-category benchmark and engineering owner task labels.']}
 OUT.write_text(json.dumps(state,indent=2)+'\n')
 text='''# Independent industrial image anomaly evaluation — new original MVTec splicing connectors\n\n**25 October 2026. Research status: PARTIAL.** This continuation tests the unresolved owner question about visual defect analyzers for actual physical equipment, rather than only image descriptions, programmatic mesh validity or small synthetic fixtures. Source is [MVTec LOCO AD](https://www.mvtec.com/research-teaching/datasets/mvtec-loco-ad) by Bergmann et al., IJCV 2022, original real industrial product photos with external source category labels distinguishing correct arrangements, logical violations and structural damage. The original 2026 SWAAG MVTec experiment used only eighteen original-color **pushpin box** photos. This new independent product is **splicing connectors**, with one hundred thirty-four different source photos selected by hash ranking from the original training, validation and test splits, and no overlapping original source filenames or image classes. The public Hugging Face rehost is pinned to its release revision in the companion evidence JSON. All source imagery is CC BY-NC-SA 4.0 **noncommercial** and lives exclusively under `/data/var`, not in SWAAG Git.\n\nThe frozen evaluation chose **twenty-four original good photographs for normal-only reference memory**, **twenty distinct good validation photographs for threshold calibration**, and **ninety different heldout source test photographs**, balanced with thirty genuinely source-labeled good, thirty logical defects and thirty structural defects. Test labels were joined only *after* all raw image features and continuous anomaly scores and the ninety-fifth percentile of twenty normal validation scores were saved. Three fixed methods shared the same number of original normal training and validation images. One used the already installed pretrained OpenAI CLIP ViT-B/32 full-image embedding, one used its last-hidden patch-embedding one-class nearest-normal memory (not the official PatchCore implementation), and one was a simple handcrafted spatial HSV histogram nearest-normal detector as a no-pretraining control. CLIP CPU-only, no shared GPU memory allocated or production services interrupted.\n\n## Independent true positives, false control alarms and missed industrial defects\n\nThe pooled case below uses the original **sixty** logical/structural anomaly source photos versus thirty independently sourced normal test photos. Binary cutoff was fixed using the twenty original normal validation photographs only, not tuned to anomaly positives. The AUC is from the actual continuous image score on unaltered real test photographs; ninety-five percent source-image stratified bootstrap intervals are descriptive only.\n\n| Predeclared image screening method | Source abnormal photographs detected | False alarms / 30 true good controls | False negatives | Real test ROC AUC | 95% source image bootstrap ROC AUC |\n|---|---:|---:|---:|---:|---|\n'''+"\n".join(rows)+"\n\n"
 text+='''The compact JSON report additionally preserves separate **logical versus normal** and **structural versus normal** source confusion matrices, false positives and negatives, normal-only calibration thresholds, number of source images, complete source hashes, and normal-only sample budget. If a model has high area under the ROC curve but its predeclared no-anomaly-calibrated cutoff misses defects, that is a deployment failure rather than a pass. Likewise zero false positives among only thirty clean samples is insufficient evidence of high deployment specificity. Source normal images cover a narrow photographic family; actual industrial defect types are visually heterogeneous. Do not extrapolate one original commercial inspection benchmark into real factory return rates, correct industrial CAD, missing components in all forklift renders, photo-realistic lighting or actual bearing-load physics.\n\n## Practical judgment tied to the owner's question\n\nA pretrained vision embedding and a domain-calibrated one-class memory can nominate suspicious patterns, but can only claim an automatic acceptance gate after seeing **independently heldout source variants, calibrated per-fault misses and control false alarms**, plus test-time cost and domain shift to the exact target assets. The very high-stakes facts in the warehouse—wrong rack orientation, missing bearing support contact, mechanical structure—must be verified from authoritative source mesh/CAD and intended load paths, not extrapolated from this photo anomaly benchmark. Where source geometry is unavailable, actual pixel detector alerts can route to human review with an explicit unknown state. No generic VLM or raw CLIP probability can prove physical soundness, photorealism, or human aesthetic quality from one picture.\n\n**Still genuinely open:** an independent manufacturer-class source-geometry-plus-human-visible render corpus of correct and defective forklift/warehouse mechanics, exact real application GUI clipping/contrast, independently adjudicated chart-arrow direction, and natural audiovisual temporal continuity anomalies. Those are distinct from original LOCO physical-object images, which are research-use-only and not a commercial deployment dataset. No previously denied media retrieval, uncertain Calendar submission, rendering pipeline or GPU process was repeated or modified.\n'''
 REPORT.write_text(text)
 print('INDUSTRIAL_NEW_REAL_SOURCE_COMPACT_REPORT',OUT.name,OUT.stat().st_size,'AND_MD',REPORT.stat().st_size,'SCORES',len(compact),'METHODS',flush=True)
if __name__=='__main__':run()
